$(document).ready(function(){$(document).on("click",".delete-service",function(event){event.preventDefault();var $this=$(this),dataurl=$this.data("url");$Confirm(function(result){result.value&&$.ajax({url:dataurl,type:"Get",dataType:"json",data:{}}).done(function(data){data.success?($notification.success("","Deleted successfully",2e3,"fa fa-check"),$this.parent().parent().remove()):$notification.error("Error!","",2e3,"fa fa-exclamation-circle")}).fail(function(jqXHR,Status){$notification.error("Error!",jqXHR.statusText,2e3,"fa fa-exclamation-circle")})})}),$(document).on("click",".toggle_publish",function(event){event.preventDefault();var $this=$(this),dataurl=$this.data("url");$this.find("i").removeClass().addClass("fa fa-spinner fa-pulse"),$.ajax({url:dataurl,type:"GET",dataType:"json",data:{}}).done(function(data){data.success?togglePublishBtn($this,!0):($notification.error("Error!","",2e3,"fa fa-exclamation-circle"),togglePublishBtn($this,!1))}).fail(function(jqXHR,Status){$notification.error("Error!",jqXHR.statusText,2e3,"fa fa-exclamation-circle"),togglePublishBtn($this,!1)})})});